{"command":"cat > main.go <<'EOF'
package main

import (
    "embed"
    "encoding/json"
    "flag"
    "fmt"
    "os"
    "path/filepath"
    "runtime"
    "sort"
    "strconv"
    "strings"
)

//go:embed assets/*
var resources embed.FS

var documentation map[string]string
var catalog string
var checkerNames []string
var checkerTags = map[string][]string{}

const defaultEnabled = "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc"

const helpText = `Usage:

    go-critic <command> [arguments...]

The commands are:

    check             run linter over specified targets
    doc               get installed checkers documentation
    help              shows help message
    version           shows version of the application

Version: v0.0.0-SNAPSHOT
`

type options struct {
    enable, disable string
    enableAll, verbose, generated, tests, shorter bool
    concurrency, exitCode int
    goVersion, cpuProfile, memProfile string
    ints map[string]*int
    bools map[string]*bool
    strs map[string]*string
}

func (o *options) integer(s string) int { return *o.ints[s] }
func (o *options) boolean(s string) bool { return *o.bools[s] }
func (o *options) text(s string) string { return *o.strs[s] }

func main() {
    b, _ := resources.ReadFile("assets/docs.json")
    _ = json.Unmarshal(b, &documentation)
    b, _ = resources.ReadFile("assets/catalog.txt")
    catalog = string(b)
    for _, l := range strings.Split(strings.TrimSpace(catalog), "\n") {
        fields := strings.Fields(strings.ReplaceAll(strings.ReplaceAll(l,"[",""),"]",""))
        checkerNames = append(checkerNames, fields[0])
        checkerTags[fields[0]] = fields[1:]
    }
    os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
    if len(args) == 0 { fmt.Fprintln(os.Stderr, "no args provided"); return 0 }
    switch args[0] {
    case "help": fmt.Print(helpText); return 0
    case "version": fmt.Println("go-critic version: v0.0.0-SNAPSHOT"); return 0
    case "doc":
        f := flag.NewFlagSet("go-critic",flag.ContinueOnError)
        f.SetOutput(os.Stderr)
        if e := f.Parse(args[1:]); e != nil { fmt.Fprintln(os.Stderr,e); return 0 }
        if f.NArg() > 1 { fmt.Fprintln(os.Stderr,"expected 0 or 1 positional arguments"); return 1 }
        if f.NArg() == 0 { fmt.Print(catalog); return 0 }
        d, ok := documentation[f.Arg(0)]
        if !ok { fmt.Fprintf(os.Stderr,"checker with name %q not found\n",f.Arg(0)); return 1 }
        fmt.Print(d); return 0
    case "check": return runCheck(args[1:])
    default:
        cmd:= args[0]
        suggestion:=""
        for _, s := range []string{"check","doc","help","version"} {
            if editDistance(cmd,s) <= 2 { suggestion=s; break }
        }
        fmt.Printf("%q unknown command",cmd)
        if suggestion!="" { fmt.Printf(", did you mean %q?",suggestion) }
        fmt.Print("\nRun \"go-critic help\" for usage.\n\n")
        fmt.Fprintf(os.Stderr,"no such command %q\n",cmd)
        return 0
    }
}
func editDistance(a,b string) int {
    d:=make([]int,len(b)+1); for i:=range d {d[i]=i}
    for i:=1;i<=len(a);i++ { p:=d[0]; d[0]=i; for j:=1;j<=len(b);j++ { q:=d[j]; n:=p; if a[i-1]!=b[j-1] {n++}; if d[j]+1<n {n=d[j]+1}; if d[j-1]+1<n{n=d[j-1]+1};d[j]=n;p=q } }
    return d[len(b)]
}

func parseOptions(args []string) (*options, []string, error) {
    o:= &options{ints:map[string]*int{},bools:map[string]*bool{},strs:map[string]*string{}}
    f:=flag.NewFlagSet("go-critic",flag.ContinueOnError)
    f.SetOutput(os.Stderr)
    // Parameter types and descriptions are part of the checkers' public interface.
    help, _ := resources.ReadFile("assets/check-help.txt")
    lines:=strings.Split(string(help),"\n")
    for i:=0;i<len(lines);i++ {
        if !strings.HasPrefix(lines[i],"  -@") { continue }
        fields:=strings.Fields(lines[i]); name:=strings.TrimPrefix(fields[0],"-")
        kind:="bool"; if len(fields)>1 {kind=fields[1]}
