func (o *options) integer(s string) int { return *o.ints[s] }
func (o *options) boolean(s string) bool { return *o.bools[s] }
func (o *options) text(s string) string { return *o.strs[s] }

func main() {
    b, _ := resources.ReadFile("assets/docs.json")
    _ = json.Unmarshal(b, &documentation)
    b, _ = resources.ReadFile("assets/catalog.txt")
    catalog = string(b)
    for _, l := range strings.Split(strings.TrimSpace(catalog), "\n") {
        fields := strings.Fields(strings.ReplaceAll(strings.ReplaceAll(l,"[",""),"]",""))
        checkerNames = append(checkerNames, fields[0])
        checkerTags[fields[0]] = fields[1:]
    }
    os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
    if len(args) == 0 { fmt.Fprintln(os.Stderr, "no args provided"); return 0 }
    switch args[0] {
    case "help": fmt.Print(helpText); return 0
    case "version": fmt.Println("go-critic version: v0.0.0-SNAPSHOT"); return 0
    case "doc":
        f := flag.NewFlagSet("go-critic",flag.ContinueOnError)
        f.SetOutput(os.Stderr)
