    f.BoolVar(&o.tests,"checkTests",true,"whether to check test files")
    f.IntVar(&o.concurrency,"concurrency",runtime.GOMAXPROCS(0),"how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
    f.StringVar(&o.cpuProfile,"cpuprofile","","write CPU profile to the specified file")
    f.StringVar(&o.disable,"disable","","comma-separated list of checkers to be disabled. Can include #tags")
    f.StringVar(&o.enable,"enable",defaultEnabled,"comma-separated list of enabled checkers. Can include #tags")
    f.BoolVar(&o.enableAll,"enableAll",false,"identical to -enable with all checkers listed. If true, -enable is ignored")
    f.IntVar(&o.exitCode,"exitCode",1,"exit code to be used when lint issues are found")
    f.StringVar(&o.goVersion,"go","","select the Go version to target. Leave as string for the latest")
    f.StringVar(&o.memProfile,"memprofile","","write memory profile to the specified file")
    f.BoolVar(&o.shorter,"shorterErrLocation",true,"whether to replace error location prefix with $GOROOT and $GOPATH")
    f.BoolVar(&o.verbose,"v",false,"whether to print output useful during linter debugging")
    e:=f.Parse(args)
    return o,f.Args(),e
}
