{"command":"cat > engine.go <<'EOF'
package main

import (
    "bytes"
    "encoding/json"
    "fmt"
    "go/ast"
    "go/constant"
    "go/importer"
    "go/parser"
    "go/printer"
    "go/token"
    "go/types"
    "io"
    "os"
    "os/exec"
    "path/filepath"
    "runtime"
    "sort"
    "strconv"
    "strings"
)

type warning struct { file,check,message,order string; line,column,offset int }
type listedPackage struct {
    Dir,ImportPath,Name string
    GoFiles,CompiledGoFiles,CgoFiles,TestGoFiles,XTestGoFiles []string
    Error *struct{ Pos,Err string }
    ForTest string
}
type context struct {
    fset *token.FileSet
    file *ast.File
    data []byte
    filename string
    info *types.Info
    opts *options
    selected map[string]bool
    warns []warning
    parents map[ast.Node]ast.Node
    imports map[string]string
    sizes types.Sizes
}

func lintTargets(targets []string, selected map[string]bool,o *options)([]warning,error){
    if len(targets)==0{return nil,nil}
    packages:=[]listedPackage{}
    anyGo:=false
    for _,t:=range targets{if strings.HasSuffix(t,".go"){anyGo=true}}
    if anyGo {
        dir:=""; files:=[]string{}
        for _,t:=range targets{
            if !strings.HasSuffix(t,".go"){return nil,fmt.Errorf("-: named files must be .go files: %s",t)}
            abs,e:=filepath.Abs(t);if e!=nil{continue}
            if _,e=os.Stat(abs);e!=nil{continue}
            d:=filepath.Dir(abs)
            if dir!="" && dir!=d{return nil,fmt.Errorf("-: named files must all be in one directory; have %s and %s",filepath.Dir(targets[0]),filepath.Dir(t))}
            dir=d;files=append(files,abs)
        }
        if len(files)>0{packages=append(packages,listedPackage{Dir:dir,ImportPath:"command-line-arguments",GoFiles:files})}
    }else{
        args:=[]string{"list","-e","-json"}
        if o.tests{args=append(args,"-test")}
        args=append(args,targets...)
        cmd:=exec.Command("go",args...)
        cmd.Env=append(os.Environ(),"GOPROXY=off","GOSUMDB=off","GOTOOLCHAIN=local")
        out,_:=cmd.Output()
        dec:=json.NewDecoder(bytes.NewReader(out))
        for {var p listedPackage;if e:=dec.Decode(&p);e!=nil{break}; if p.Dir!="" && len(p.GoFiles)+len(p.CgoFiles)>0{packages=append(packages,p)}}
    }
    var warns []warning
    already:=map[string]bool{}
    imp:=newPackageImporter()
    for _,p:=range packages{
        fs:=token.NewFileSet(); var files []*ast.File
        contents:=map[*ast.File][]byte{}
        for _,f:=range append(p.GoFiles,p.CgoFiles...){
            if !filepath.IsAbs(f){f=filepath.Join(p.Dir,f)}
            if already[f] {continue}
            if !o.tests&&strings.HasSuffix(f,"_test.go"){continue}
            data,e:=os.ReadFile(f);if e!=nil{continue}
            node,_:=parser.ParseFile(fs,f,data,parser.ParseComments|parser.AllErrors)
            if node==nil{continue}
            already[f]=true
            files=append(files,node); contents[node]=data
        }
        if len(files)==0 {continue}
        if o.verbose{debug("checking %q package (%d files)",p.ImportPath,len(files))}
        info:=&types.Info{Types:map[ast.Expr]types.TypeAndValue{},Defs:map[*ast.Ident]types.Object{},Uses:map[*ast.Ident]types.Object{},Selections:map[*ast.SelectorExpr]*types.Selection{},Scopes:map[ast.Node]*types.Scope{},Implicits:map[ast.Node]types.Object{}}
        sizes:=types.SizesFor("gc",runtime.GOARCH)
        conf:=types.Config{Importer:imp,Error:func(error){},Sizes:sizes,DisableUnusedImportCheck:true}
        // Go errors do not prevent unrelated checks from examining a partial tree.
        func(){defer func(){recover()}();_,_=conf.Check(p.ImportPath,fs,files,info)}()
        sort.SliceStable(files,func(i,j int)bool{return fs.Position(files[i].Pos()).Filename<fs.Position(files[j].Pos()).Filename})
        for _,f:=range files{
            c:=&context{fset:fs,file:f,data:contents[f],info:info,opts:o,selected:selected,parents:map[ast.Node]ast.Node{},imports:map[string]string{},sizes:sizes}
            c.filename=fs.Position(f.Pos()).Filename
            if !o.generated && isGenerated(c.data){continue}
            for _,im:=range f.Imports {s,_:=strconv.Unquote(im.Path.Value);name:=filepath.Base(s);if im.Name!=nil{name=im.Name.Name};c.imports[name]=s}
            var stack []ast.Node
            ast.Inspect(f,func(n ast.Node)bool{if n==nil{stack=stack[:len(stack)-1];return false};if len(stack)>0{c.parents[n]=stack[len(stack)-1]};stack=append(stack,n);return true})
            c.checkFile()
            warns=append(warns,c.warns...)
        }
    }
    return warns,nil
}

// Import type information from Go's compiler, never from the program being emulated.
type packageImporter struct { standard types.Importer; cache map[string]*types.Package }
func newPackageImporter()*packageImporter {
    i:=&packageImporter{cache:map[string]*types.Package{}}
    lookup:=func(path string)(io.ReadCloser,error){
        cmd:=exec.Command("go","list","-e","-export","-f","{{.Export}}",path)
        cmd.Env=append(os.Environ(),"GOPROXY=off","GOSUMDB=off","GOTOOLCHAIN=local")
        data,err:=cmd.Output(); if err!=nil{return nil,err}
        return os.Open(strings.TrimSpace(string(data)))
    }
    i.standard=importer.ForCompiler(token.NewFileSet(),"gc",lookup)
    return i
}
func (i *packageImporter) Import(path string)(*types.Package,error){
    if p:=i.cache[path];p!=nil{return p,nil}
    p,e:=i.standard.Import(path);if p!=nil{i.cache[path]=p};return p,e
}

func isGenerated(data []byte)bool {
    for _,line:=range strings.Split(string(data),"\n"){
        if strings.HasPrefix(line,"// Code generated ") && strings.HasSuffix(line," DO NOT EDIT."){return true}
    }
    return false
}
func (c *context) warn(check string,n ast.Node,format string,args ...interface{}){
    if !c.selected[check]||n==nil{return}
    c.warnAt(check,n.Pos(),fmt.Sprintf(format,args...))
}
var textOrdered=map[string]bool{"argOrder":true,"assignOp":true,"dupArg":true,"unslice":true,"wrapperFunc":true,"emptyDecl":true,"regexpMust":true,"yodaStyleExpr":true}
func (c *context) warnAt(check string,pos token.Pos,message string){
    if !c.selected[check]{return}
    p:=c.fset.Position(pos)
    filename:=p.Filename
    wd,_:=os.Getwd()
    if rel,e:=filepath.Rel(wd,filename);e==nil && rel!=".."&&!strings.HasPrefix(rel,"../") {filename="./"+filepath.ToSlash(rel)}
    if c.opts.shorter {
        root:=runtime.GOROOT();if strings.HasPrefix(filename,root+"/"){filename="$GOROOT"+strings.TrimPrefix(filename,root)}
        gp:=os.Getenv("GOPATH");if gp==""{home,_:=os.UserHomeDir();gp=filepath.Join(home,"go")};for _,s:=range filepath.SplitList(gp){if s!=""&&strings.HasPrefix(filename,s+"/"){filename="$GOPATH"+strings.TrimPrefix(filename,s);break}}
    }
    order:="";if textOrdered[check]{order=message}
    c.warns=append(c.warns,warning{file:filename,check:check,message:message,order:order,line:p.Line,column:p.Column,offset:p.Offset})
}
func nodeString(n interface{})string {
    if n==nil{return ""}
    var b bytes.Buffer
    _=printer.Fprint(&b,token.NewFileSet(),n)
    return b.String()
}
func (c *context) source(n ast.Node)string {
    if n==nil{return ""}
    start:=c.fset.PositionFor(n.Pos(),false).Offset
    end:=c.fset.PositionFor(n.End(),false).Offset
    if start>=0&&end>=start&&end<=len(c.data){return string(c.data[start:end])}
    return nodeString(n)
}
func unparen(e ast.Expr)ast.Expr {for{p,ok:=e.(*ast.ParenExpr);if !ok{return e};e=p.X}}
func ident(e ast.Expr,s string)bool {i,ok:=unparen(e).(*ast.Ident);return ok&&i.Name==s}
func same(a,b ast.Expr)bool{return a!=nil&&b!=nil&&nodeString(unparen(a))==nodeString(unparen(b))}
func (c *context) typeOf(e ast.Expr)types.Type {if e==nil{return nil};return c.info.TypeOf(e)}
func underlying(t types.Type)types.Type {if t==nil{return nil};return t.Underlying()}
func (c *context) isBasic(e ast.Expr, flags types.BasicInfo)bool {b,ok:=underlying(c.typeOf(e)).(*types.Basic);return ok&&b.Info()&flags!=0}
func (c *context) constValue(e ast.Expr)constant.Value{if e==nil{return nil};return c.info.Types[e].Value}
func (c *context) intValue(e ast.Expr)(int64,bool) {
    if v:=c.constValue(e);v!=nil&&v.Kind()==constant.Int{return constant.Int64Val(v)}
    if lit,ok:=unparen(e).(*ast.BasicLit);ok&&lit.Kind==token.INT{v,e:=strconv.ParseInt(lit.Value,0,64);return v,e==nil}
    if u,ok:=unparen(e).(*ast.UnaryExpr);ok&&u.Op==token.SUB{v,b:=c.intValue(u.X);return -v,b}
    return 0,false
}
func (c *context) stringValue(e ast.Expr)(string,bool){
    if v:=c.constValue(e);v!=nil&&v.Kind()==constant.String{return constant.StringVal(v),true}
    if lit,ok:=unparen(e).(*ast.BasicLit);ok&&lit.Kind==token.STRING {s,err:=strconv.Unquote(lit.Value);return s,err==nil}
    return "",false
}
func (c *context) isInt(e ast.Expr,n int64)bool{v,ok:=c.intValue(e);return ok&&v==n}
func (c *context) callName(call *ast.CallExpr)string {
    if call==nil{return ""}
    switch f:=unparen(call.Fun).(type) {
    case *ast.Ident:
        if obj:=c.info.Uses[f];obj!=nil&&obj.Pkg()!=nil{return obj.Pkg().Path()+"."+f.Name}
        return f.Name
    case *ast.SelectorExpr:
        if id,ok:=f.X.(*ast.Ident);ok {if path:=c.imports[id.Name];path!=""{return path+"."+f.Sel.Name}}
        return nodeString(f)
    }
    return nodeString(call.Fun)
