package main

import (
    "fmt"
    "go/ast"
    "go/parser"
    "go/token"
    "os"
    "path/filepath"
    "runtime"
    "strconv"
    "strings"
)

// Rule files are Go programs. In an offline installation the optional DSL
// import may be unavailable; report this in the same phase as other rule-file
// parsing errors, without preventing the ordinary checkers from running.
func initializeRules(o *options) error {
    input:=o.text("ruleguard.rules")
    if input==""{return nil}
    failed,loaded:=false,false
    failOn:=stringSet(o.text("ruleguard.failOn"))
    fatal:=o.boolean("ruleguard.failOnError")||failOn["all"]||failOn["dsl"]
    for _,pattern:=range strings.Split(input,","){
        files,err:=filepath.Glob(pattern)
        if err!=nil{fmt.Fprintln(os.Stderr,"ruleguard init error:",err);return nil}
        if len(files)==0{return fmt.Errorf("ruleguard init error: no file matching '%s'",pattern)}
        for _,path:=range files{
            fset:=token.NewFileSet()
            file,err:=parser.ParseFile(fset,path,nil,parser.ParseComments)
            message:=""
            if err!=nil {message="parse file error: "+err.Error()} else {
                const dsl="github.com/quasilyte/go-ruleguard/dsl"
                line,column:=2,8
                explicit:=false
                for _,im:=range file.Imports {p,_:=strconv.Unquote(im.Path.Value);if p==dsl{pos:=fset.Position(im.Path.Pos());line,column=pos.Line,pos.Column;explicit=true;break}}
                hasContent:=false
                for _,d:=range file.Decls{if g,ok:=d.(*ast.GenDecl);!ok||g.Tok!=token.IMPORT{hasContent=true}}
                if explicit||hasContent {
                    prefix:="";if !explicit{prefix="parse custom decls: "}
                    message=fmt.Sprintf("%stypechecker error: %s:%d:%d: could not import %s (can't find import: %q: cannot find package %q in any of:\n%s)",prefix,path,line,column,dsl,dsl,dsl,missingImportLocations(dsl))
                }
            }
            if message!=""{
                if fatal{return fmt.Errorf("ruleguard init error: %s",message)}
                fmt.Fprintf(os.Stderr,"ruleguard init error, skip %s: %s\n",path,message)
                failed=true
            }else{loaded=true}
        }
    }
    o.ruleguardBroken=failed&&!loaded
    return nil
}
func missingImportLocations(path string)string{
    root:=runtime.GOROOT()
    lines:=[]string{}
    if root==""{lines=append(lines,"\t($GOROOT not set)")}else{lines=append(lines,"\t"+filepath.Join(root,"src",path)+" (from $GOROOT)")}
    gp:=os.Getenv("GOPATH");if gp==""{home,_:=os.UserHomeDir();gp=filepath.Join(home,"go")}
    for _,p:=range filepath.SplitList(gp){lines=append(lines,"\t"+filepath.Join(p,"src",path)+" (from $GOPATH)")}
    return strings.Join(lines,"\n")
}
EOF
